from tests_src import T, Q2, TF

T(24, "24-7", "Round the World in Seventy-Two Days", "Recount (Historical)", [
"Nellie Bly was a newspaper reporter who worked for the New York World, a paper that thousands of people read every day. Nellie was fond of adventure, and in 1888, she had a bold idea. Many readers knew a famous story by Jules Verne, in which a gentleman called Phileas Fogg travels around the world in eighty days. Nellie wondered whether a real person could do the same, or even do it faster. She asked her editor if she could try.",
"On the 14th of November 1889, Nellie boarded a steamship at Hoboken, a port near New York, and set off across the Atlantic Ocean. She wanted to move quickly, so she took just one small bag. The crossing took eight days, and she then went on by train to France. There, in the town of Amiens, she visited Jules Verne himself. He wished her luck and told her that if she finished in seventy-nine days, he would applaud with both hands.",
"For weeks after that, Nellie hurried from one place to the next by train and by ship. She passed through the Suez Canal, a waterway that joins two seas, and visited Colombo, Singapore, Hong Kong and Japan. In Singapore, she bought a pet monkey. Every ship and train had to leave on time, because a single delay could wreck her plan. The longest stretch of all was the voyage across the Pacific Ocean, which lasted fourteen days.",
"When Nellie reached San Francisco, her newspaper arranged a special train to carry her across America. At 51 minutes past 3 o’clock in the afternoon on the 25th of January 1890, the train pulled into Jersey City, close to where she had begun. Nellie had travelled about 25,000 miles in 72 days, 6 hours and 11 minutes. She had beaten Phileas Fogg’s made-up record by more than a week.",
"Nellie did not know it, but she had been in a race. A reporter named Elizabeth Bisland had left New York on the same day, heading around the world in the opposite direction for a magazine. Elizabeth was still travelling when Nellie arrived home, and Nellie won by about four days.",
"Nellie’s journey showed what a determined reporter with one small bag could do. Her newspaper printed stories about the trip, so that readers could follow what she had seen and done.",
], [
 dict(d="2b",k="mc",m=1,q="Who wrote the story that gave Nellie her idea?",opts=["Elizabeth Bisland","Phileas Fogg","Jules Verne","Her editor"],a="C"),
 dict(d="2b",k="short",m=1,q="How many bags did Nellie take on her journey?",a="One (small) bag.",g="Accept one / a single small bag."),
 dict(d="2a",k="mc",m=1,q="In paragraph 1, what does the word “bold” mean?",opts=["Brave and daring","Old-fashioned","Very quiet","Rather silly"],a="A"),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in.",items=["Nellie crossed the Pacific Ocean.","Nellie visited Jules Verne in Amiens.","Nellie asked her editor if she could try.","A special train carried Nellie across America."],a=[3,2,1,4],g=Q2),
 dict(d="2b",k="find",m=1,q="In paragraph 3, find and copy the words that tell you what a Suez Canal is.",a="a waterway that joins two seas",g="Accept “a waterway that joins two seas”."),
 dict(d="2d",k="short",m=1,q="Why did Nellie need every ship and train to leave on time?",a="A delay could wreck her plan / she might not finish in time.",g="Accept any answer that links delays to failing to complete the journey quickly."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Nellie started her journey from Hoboken.","The Pacific voyage took fourteen days.","Nellie met Jules Verne in Japan.","Elizabeth Bisland travelled in the same direction as Nellie."],a=["T","T","F","F"],g=TF),
 dict(d="2d",k="short",m=1,q="What tells you that Nellie was in a hurry throughout her journey?",a="She took only one small bag / she hurried from place to place / delays could wreck her plan.",g="Accept any one relevant detail from the text."),
 dict(d="2a",k="mc",m=1,q="In paragraph 4, what does “made-up” mean in the phrase “Phileas Fogg’s made-up record”?",opts=["Very fast","Painted","Invented in a story","Written on paper"],a="C"),
 dict(d="2d",k="short",m=1,q="Nellie beat Phileas Fogg’s record by more than a week. How can you tell this from the text?",a="Fogg took eighty days and Nellie took 72 days, which is eight days fewer.",g="Accept: 80 minus 72 is 8 / she took 72 days but Fogg took eighty."),
 dict(d="2d",k="short",m=1,q="Nellie “did not know it, but she had been in a race”. Explain why this was true.",a="Another reporter, Elizabeth Bisland, was travelling round the world the other way at the same time.",g="Accept any answer that mentions Elizabeth Bisland also travelling round the world at the same time."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the whole text?",opts=["A reporter beat the time of a story character.","A monkey helped a reporter to win a difficult race.","Trains are always quicker than ships are.","A newspaper was sold in many countries."],a="A"),
])

T(25, "25-7", "Alone on the Ocean", "Recount (Historical)", [
"Ellen MacArthur was born on the 8th of July 1976 in Derbyshire, a county in the middle of England, far from the sea. As a young child, she went out on a boat belonging to her aunt on the east coast, and she loved it at once. From then on, Ellen dreamed of sailing. She saved her money for years until she could buy a small dinghy, which is a little boat with a single sail, and she began to learn how to handle it.",
"Ellen worked hard to improve, and soon she was sailing longer and longer distances. Her next goal was more ambitious. She wanted to enter the Vendée Globe, a race in which each sailor travels around the world alone, without stopping and without any help. It is one of the hardest challenges in sailing, and it takes months to complete. In 2001, Ellen finished the race in second place. She was only 24, and she was the youngest person ever to finish it.",
"Ellen was not finished. She wanted to try to beat the world record for sailing around the world alone. To do this, she needed a much faster boat, so she sailed a trimaran, which has three long, narrow hulls instead of one. Her boat, called B&Q, was about 23 metres long. In November 2004, she set off from Falmouth, a port in the south-west of England, and sailed alone across the seas for the next ten weeks.",
"During the voyage, Ellen could only snatch short naps, because the boat needed her attention all the time. She also had to mend and steer the boat by herself. Even so, she kept going, one day after another, until the finish was in sight.",
"On the 7th of February 2005, Ellen sailed back into Falmouth. Her journey had taken just over 71 days, which was more than a day faster than any sailor before her. Thousands of people crowded the harbour to cheer, and boats of every size sailed out to meet her. She was 28 years old. Soon afterwards, she was given the title of Dame, and she was the youngest person to have received it at the time.",
"Ellen used her fame to help others. In 2003, she had set up a charity, the Ellen MacArthur Cancer Trust, which takes young people sailing to help them rebuild their confidence. Later, in 2010, she launched the Ellen MacArthur Foundation. Its aim is to encourage people and businesses to use things again and again, so that less is wasted. Ellen’s journeys showed what a person with a big dream and plenty of patience could do.",
], [
 dict(d="2b",k="mc",m=1,q="Where did Ellen first go sailing as a young child?",opts=["On a lake in Derbyshire","On a large racing boat","On her aunt’s boat","On a ship in Falmouth"],a="C"),
 dict(d="2a",k="find",m=1,q="In paragraph 1, find and copy the word that means “a little boat with a single sail”.",a="dinghy",g="Accept “dinghy” only."),
 dict(d="2b",k="short",m=1,q="How old was Ellen when she finished second in the Vendée Globe?",a="24.",g="Accept 24 / twenty-four."),
 dict(d="2d",k="short",m=1,q="Ellen “saved her money for years” to buy a dinghy. What does this tell you about her?",a="She was patient and determined / she really wanted to sail.",g="Accept any answer showing determination, patience or strong desire to sail."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in.",items=["Ellen set off from Falmouth in B&Q.","Ellen finished second in the Vendée Globe.","Ellen was given the title of Dame.","Ellen bought a dinghy."],a=[3,2,4,1],g=Q2),
 dict(d="2b",k="short",m=2,q="Give two rules of the Vendée Globe race.",a="Each sailor sails alone; without stopping; without any help.",g="1 mark for each rule from paragraph 2. Max 2."),
 dict(d="2d",k="short",m=1,q="Why did Ellen need a trimaran to try to beat the world record?",a="She needed a much faster boat.",g="Accept: trimarans are faster / it was faster than her earlier boat."),
 dict(d="2a",k="mc",m=1,q="In paragraph 2, what does the word “ambitious” mean?",opts=["Easy to do and quick to finish","Needing great effort and courage","Cheap for most sailors to try","Silly and far too dangerous"],a="B"),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Ellen was born close to the sea.","B&Q had three hulls.","Ellen could sleep for many hours each night during the voyage.","Ellen returned to Falmouth on the 7th of February 2005."],a=["F","T","F","T"],g=TF),
 dict(d="2d",k="short",m=1,q="“Her journey had taken just over 71 days, which was more than a day faster than any sailor before her.” What does this tell you about the record?",a="Ellen had beaten the record / she was now the fastest.",g="Accept any answer showing Ellen set a new record."),
 dict(d="2d",k="short",m=1,q="How can you tell that many people were interested in Ellen’s voyage? Give one piece of evidence.",a="Thousands crowded the harbour to cheer / boats sailed out to meet her.",g="Accept either."),
 dict(d="2g",k="short",m=1,q="The text says Ellen could only “snatch short naps”. What does the word “snatch” suggest about her sleep?",a="It was quick and taken whenever she could.",g="Accept: hurried, brief, in gaps between jobs."),
 dict(d="2c",k="mc",m=1,q="Which of these is the best heading for paragraph 6?",opts=["How Ellen helped others","Ellen builds a new boat for a race","Ellen wins her first sailing race","A day in the life of a sailor"],a="A"),
])

T(26, "26-7", "The Girl Who Climbed Mount Nasu", "Recount (Historical)", [
"Junko Tabei was born on the 22nd of September 1939 in Miharu, a town in Japan. She was the fifth of seven children. When she was ten years old, her class went on a school trip to climb Mount Nasu, and she was captivated. From then on she wanted to climb as many mountains as she could.",
"Junko studied English and American literature at university, and afterwards she looked for other climbers to join. At that time, most of the clubs were run by men, and some people did not think women should be mountaineers. Junko did not let this stop her. She climbed with the men’s clubs, and she worked her way up many of the great peaks of Japan, including the famous Mount Fuji.",
"In 1969, Junko decided that women should have a club of their own. She founded the Ladies Climbing Club, and its motto was: “Let’s go on an overseas expedition by ourselves.” The members trained together, and their great goal was to climb Mount Everest, the highest mountain on Earth.",
"An expedition to Everest was very expensive, and at first Junko struggled to find enough money. Each member of the team had to pay part of the cost. Junko taught piano lessons to raise her share, and she worked as an editor. Later, a newspaper and a television company agreed to help pay for the trip. The team even made some of their own clothing and equipment, because there was very little made in women’s sizes.",
"In the spring of 1975, fifteen women set off for the Himalayas, the great mountain range where Everest stands. The team climbed slowly and carefully up the great mountain. Junko worked with a Sherpa guide named Ang Tsering, a member of the mountain people who live in that region. On the 16th of May 1975, the two of them reached the top of Everest. Junko became the first woman ever to stand on the highest point on Earth.",
"Junko did not stop there. She set herself a new challenge: to climb the highest mountain on every continent. She climbed peaks on continent after continent, and in 1992 she became the first woman to complete the set.",
"Junko also cared about the mountains themselves. She worked to protect mountain environments and to share her love of climbing with young people. For Junko, a mountain was never just something to be conquered. It was a place to be respected, to be enjoyed and to be looked after.",
], [
 dict(d="2b",k="short",m=1,q="How old was Junko when her class climbed Mount Nasu?",a="Ten.",g="Accept 10 / ten years old."),
 dict(d="2a",k="mc",m=1,q="In paragraph 1, what does the word “captivated” mean?",opts=["Tired","Frightened","Completely fascinated","Bored"],a="C"),
 dict(d="2d",k="short",m=1,q="Why did Junko join men’s climbing clubs after university?",a="Most of the clubs were run by men / there were few clubs for women / she wanted to climb.",g="Accept any answer linking to most clubs being run by men or wanting to climb."),
 dict(d="2d",k="short",m=1,q="“Junko did not let this stop her.” What does this tell you about her?",a="She was determined / she kept going even when people doubted her.",g="Accept: determined, brave, or refused to give up."),
 dict(d="2b",k="find",m=1,q="In paragraph 3, find and copy the motto of the Ladies Climbing Club.",a="Let’s go on an overseas expedition by ourselves.",g="Accept the motto with or without the full stop."),
 dict(d="2b",k="short",m=2,q="Give two ways Junko and her team dealt with the cost of the Everest expedition.",a="Junko taught piano lessons; she worked as an editor; a newspaper and television company helped pay; the team made some of their own clothing and equipment.",g="1 mark for each way. Max 2."),
 dict(d="2d",k="short",m=1,q="Why did the team make some of their own clothing and equipment?",a="There was very little made in women’s sizes.",g="Accept: it was hard to find clothing to fit women."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in.",items=["Junko reached the top of Everest.","Junko started the Ladies Climbing Club.","Junko climbed Mount Nasu on a school trip.","Junko became the first woman to climb the highest mountain on every continent."],a=[3,2,1,4],g=Q2),
 dict(d="2a",k="mc",m=1,q="In paragraph 4, what does the word “expedition” mean?",opts=["A long journey with a goal","A quick walk to the shops","A special type of clothing","A club for mountain lovers"],a="A"),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Junko was born in Miharu.","Fifteen women went to the Himalayas.","Ang Tsering was a member of Junko’s club.","Junko was the first woman to complete the climb of the highest mountain on each continent."],a=["T","T","F","T"],g=TF),
 dict(d="2g",k="short",m=1,q="In the last paragraph, the writer says a mountain was “never just something to be conquered”. What does this tell you about how Junko felt about mountains?",a="She respected them and wanted to enjoy and look after them, not just win against them.",g="Accept any answer showing that she respected or cared for mountains rather than seeing them as a challenge to beat."),
 dict(d="2e",k="short",m=1,q="What do you think Junko might have said to a young person who wanted to start climbing? Use the text to help you.",a="Any sensible encouragement, e.g. Go for it / look after the mountains / do not let others stop you.",g="Accept any answer that fits Junko’s determination or care for mountains."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the whole text?",opts=["A climber worked with a Sherpa guide on one mountain in the Himalayas.","A girl who loved mountains became a pioneering climber.","Mount Fuji is the tallest mountain in the whole of Japan.","Climbing a mountain can cost a great deal of money."],a="B"),
])
